-- Nạp các sự kiện chính tại Đường Sách

INSERT INTO events (id, title, title_en, slug, theme, venue_id, start_at, end_at, status, priority_level, description, summary, cover_image_url, created_by, published_at) VALUES
  ('daa1f312-395e-43a2-a91c-00f3a3d50bbb', 'Lễ hội Đường Sách Mùa Thu 2026', 'Autumn Book Street Festival 2026', 'le-hoi-duong-sach-mua-thu-2026', 'Mùa Thu & Những Trang Sách Kết Nối Tri Thức', '569210e0-e140-4ece-a8e1-0b67e32a3404', NOW() - INTERVAL '2 days', NOW() + INTERVAL '5 days', 'published'::event_status, 'high'::event_priority, 'Lễ hội thường niên quy tụ hàng trăm đầu sách mới, chương trình ký tặng của các tác giả tên tuổi và chuỗi tọa đàm nghệ thuật xuất bản.', 'Hội tụ sách hay, hoạt động hấp dẫn và không gian văn hóa dành cho mọi người.', 'https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=1200&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW()),
  ('7e579f11-c470-4788-a0ef-3cc29525e16e', 'Hội Sách Thiếu Nhi Hè 2026', 'Summer Children Book Fair 2026', 'hoi-sach-thieu-nhi-he-2026', 'Mở Trang Sách Sáng Tạo Mùa Hè Rực Rỡ', '569210e0-e140-4ece-a8e1-0b67e32a3404', NOW() + INTERVAL '10 days', NOW() + INTERVAL '15 days', 'published'::event_status, 'high'::event_priority, 'Ngày hội dành riêng cho các bạn nhỏ với hàng ngàn đầu sách tranh truyện, workshop khoa học và góc đọc tương tác.', 'Không gian vui chơi và đọc sách bổ ích cho thiếu nhi.', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=1200&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW())
  ,('7f8440a3-f528-41cf-a79e-5e348c69ffbd', 'Giao lưu tác giả: "Sài Gòn - Ký ức qua từng trang sách xưa"', 'Author Talk: "Saigon - Memories Through Vintage Pages"', 'event-event-01', '', '569210e0-e140-4ece-a8e1-0b67e32a3404', '2026-10-03T02:00:00.000Z'::timestamptz, '2026-10-03T04:00:00.000Z'::timestamptz, 'published'::event_status, 'regular'::event_priority, 'Buổi trò chuyện cùng nhà văn hóa và các nhà sưu tầm tư liệu cổ về sự chuyển mình của phố xá Sài Gòn - TP.HCM qua các ấn phẩm từ thế kỷ 20.', 'Buổi trò chuyện cùng nhà văn hóa và các nhà sưu tầm tư liệu cổ về sự chuyển mình của phố xá Sài Gòn - TP.HCM qua các ấn phẩm từ thế kỷ 20.', 'https://images.unsplash.com/photo-1475721027785-f74eccf877e2?auto=format&fit=crop&w=800&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW())
  ,('ea33ca1c-8d28-45e4-a4d2-003886dd02e4', 'Ra mắt sách mới: "Thành phố dưới những tán cây xanh"', 'Book Launch: "The City Beneath Green Canopies"', 'event-event-03', '', '569210e0-e140-4ece-a8e1-0b67e32a3404', '2026-10-07T07:00:00.000Z'::timestamptz, '2026-10-07T09:00:00.000Z'::timestamptz, 'published'::event_status, 'regular'::event_priority, 'Giới thiệu tập tản văn và ký họa đô thị của các bạn trẻ TP.HCM với góc nhìn xanh, bền vững và đầy nhựa sống về đường phố Sài Gòn.', 'Giới thiệu tập tản văn và ký họa đô thị của các bạn trẻ TP.HCM với góc nhìn xanh, bền vững và đầy nhựa sống về đường phố Sài Gòn.', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=800&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW())
  ,('2af4a35d-5ea0-4c33-acd2-de6ec9be9d0b', 'Triển lãm & Tọa đàm: "Ký họa Di sản Kiến trúc Sài Gòn qua tranh vẽ"', 'Exhibition & Talk: "Saigon Architectural Heritage Through Sketches"', 'event-event-05', '', '569210e0-e140-4ece-a8e1-0b67e32a3404', '2026-10-12T02:00:00.000Z'::timestamptz, '2026-10-12T10:00:00.000Z'::timestamptz, 'published'::event_status, 'high'::event_priority, 'Trưng bày 50 tác phẩm ký họa màu nước về các công trình kiến trúc cổ Sài Gòn và giao lưu cùng nhóm Urban Sketchers Vietnam.', 'Trưng bày 50 tác phẩm ký họa màu nước về các công trình kiến trúc cổ Sài Gòn và giao lưu cùng nhóm Urban Sketchers Vietnam.', 'https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=800&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW())
  ,('bde2daf8-061d-4ae1-adeb-db8dd283e9c9', 'Ngày hội Đọc sách Thiếu nhi: "Phiêu lưu cùng Dế Mèn & Những người bạn"', 'Children Reading Festival: "Adventures of Cricket & Friends"', 'event-event-06', '', '569210e0-e140-4ece-a8e1-0b67e32a3404', '2026-10-17T01:30:00.000Z'::timestamptz, '2026-10-17T10:00:00.000Z'::timestamptz, 'published'::event_status, 'medium'::event_priority, 'Không gian kịch rối tương tác, đọc sách thiếu nhi và thi vẽ tranh minh họa nhận sách tặng dành cho các bé và gia đình.', 'Không gian kịch rối tương tác, đọc sách thiếu nhi và thi vẽ tranh minh họa nhận sách tặng dành cho các bé và gia đình.', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=800&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW())
  ,('89c22dc5-645b-4528-a081-8dc42a29b834', 'Đêm Thơ Nhạc Sài Gòn: "Giai điệu phố & Lời ru của sông"', 'Saigon Poetry & Acoustic Night: "Street Melodies & River Lullabies"', 'event-event-07', '', '569210e0-e140-4ece-a8e1-0b67e32a3404', '2026-10-22T11:30:00.000Z'::timestamptz, '2026-10-22T14:00:00.000Z'::timestamptz, 'published'::event_status, 'high'::event_priority, 'Không gian giao lưu thơ ca, ngâm thơ và biểu diễn guitar mộc mạc tôn vinh vẻ đẹp trữ tình của các thi phẩm về Sài Gòn xưa và nay.', 'Không gian giao lưu thơ ca, ngâm thơ và biểu diễn guitar mộc mạc tôn vinh vẻ đẹp trữ tình của các thi phẩm về Sài Gòn xưa và nay.', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=800&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW())
  ,('849259d6-ccfe-47fb-a90a-8a6f0c7aba9b', 'Workshop Nghệ Thuật: "Thực hành Đóng sách Thủ công & Khắc Mộc Bản"', 'Craft Workshop: "Handmade Bookbinding & Woodblock Printing"', 'event-event-08', '', '569210e0-e140-4ece-a8e1-0b67e32a3404', '2026-10-26T02:00:00.000Z'::timestamptz, '2026-10-26T05:00:00.000Z'::timestamptz, 'published'::event_status, 'medium'::event_priority, 'Bạn đọc được trực tiếp hướng dẫn khâu gáy sách kiểu cổ truyền, làm bìa sách giấy dó và in ấn tranh khắc gỗ truyền thống mang về.', 'Bạn đọc được trực tiếp hướng dẫn khâu gáy sách kiểu cổ truyền, làm bìa sách giấy dó và in ấn tranh khắc gỗ truyền thống mang về.', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=800&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW())
  ,('8e98d3f6-859c-45ca-ab9f-508d54e8f932', 'Tọa đàm Chuyên sâu: "Văn hóa Đọc trong Kỷ nguyên Trí tuệ Nhân tạo (AI)"', 'Panel Discussion: "Reading Culture in the Age of Artificial Intelligence"', 'event-event-09', '', '569210e0-e140-4ece-a8e1-0b67e32a3404', '2026-10-30T07:00:00.000Z'::timestamptz, '2026-10-30T09:30:00.000Z'::timestamptz, 'published'::event_status, 'high'::event_priority, 'Các chuyên gia công nghệ, nhà xuất bản và nhà giáo dục đối thoại về cách AI hỗ trợ việc học tập, bảo tồn di sản tri thức và nuôi dưỡng niềm say mê đọc sách.', 'Các chuyên gia công nghệ, nhà xuất bản và nhà giáo dục đối thoại về cách AI hỗ trợ việc học tập, bảo tồn di sản tri thức và nuôi dưỡng niềm say mê đọc sách.', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&w=800&q=80', '87427bb9-732b-44b3-aed9-18938ae98fe9', NOW())
